			return CRDTSnapshot{}, err
		}
	case CRDTTypeRegister:
		if err := compactRegisterOps(tx, documentID); err != nil {
			return CRDTSnapshot{}, err
		}
	case CRDTTypeORSet:
		if err := compactORSetOps(tx, documentID); err != nil {
			return CRDTSnapshot{}, err
		}
	}

