	state, err := s.GetCRDTState("doc")
	if err != nil {
		t.Fatal(err)
	}
	if state.Type != CRDTTypeCounter {
		t.Fatalf("type = %q", state.Type)
	}
	if string(state.Value) != "11" { // 9 + 2 + 0
		t.Fatalf("merged value = %s, want 11", state.Value)
