	// New elements still merge after compaction.
	submitCRDT(t, s, "doc", CRDTTypeGSet, CRDTOp{ID: "g4", DeviceID: "dev-1", Elements: []string{"date"}})
	if got := crdtStateValue(t, s, "doc"); got != `["apple","banana","cherry","date"]` {
